-- Focused PR #22 schema fixture: actual table/column names and memory triggers.
-- Complete five-migration upgrade is a separate integration gate (tools/verify-upstream.mjs).
PRAGMA foreign_keys=ON;
CREATE TABLE accounts(id TEXT PRIMARY KEY,disabled_at INTEGER);
CREATE TABLE organizations(id TEXT PRIMARY KEY,disabled_at INTEGER);
CREATE TABLE account_emails(id TEXT PRIMARY KEY,account_id TEXT REFERENCES accounts(id),address TEXT,domain TEXT,verified_at INTEGER,revoked_at INTEGER,UNIQUE(id,account_id));
CREATE UNIQUE INDEX one_live_email_claim ON account_emails(address) WHERE revoked_at IS NULL;
CREATE TABLE memberships(id TEXT PRIMARY KEY,organization_id TEXT REFERENCES organizations(id),account_id TEXT REFERENCES accounts(id),email_id TEXT,role TEXT,expires_at INTEGER DEFAULT 9007199254740991,revoked_at INTEGER,UNIQUE(id,account_id,email_id),FOREIGN KEY(email_id,account_id) REFERENCES account_emails(id,account_id));
CREATE TABLE credentials(id TEXT PRIMARY KEY,account_id TEXT REFERENCES accounts(id),membership_id TEXT,email_id TEXT,kind TEXT,token_digest TEXT UNIQUE,expires_at INTEGER,reauthenticated_at INTEGER,revoked_at INTEGER,permission TEXT DEFAULT 'write');
CREATE VIEW active_memberships AS SELECT m.* FROM memberships m JOIN accounts a ON a.id=m.account_id AND a.disabled_at IS NULL JOIN organizations o ON o.id=m.organization_id AND o.disabled_at IS NULL JOIN account_emails e ON e.id=m.email_id AND e.account_id=m.account_id AND e.revoked_at IS NULL WHERE m.revoked_at IS NULL;
CREATE VIEW active_credentials AS SELECT c.*,coalesce(m.expires_at,9007199254740991) AS membership_expires_at FROM credentials c JOIN accounts a ON a.id=c.account_id AND a.disabled_at IS NULL LEFT JOIN active_memberships m ON m.id=c.membership_id AND m.account_id=c.account_id AND m.email_id=c.email_id WHERE c.revoked_at IS NULL AND (c.kind IN ('session','personal_key') OR m.id IS NOT NULL);
CREATE TABLE spaces(id TEXT PRIMARY KEY,name TEXT,account_id TEXT REFERENCES accounts(id),organization_id TEXT REFERENCES organizations(id),security_mode TEXT DEFAULT 'managed',created_at INTEGER,actor_credential_id TEXT REFERENCES credentials(id));
CREATE TABLE memories(id TEXT PRIMARY KEY,space_id TEXT REFERENCES spaces(id),body TEXT NOT NULL CHECK(length(CAST(body AS BLOB)) BETWEEN 1 AND 16384),source TEXT,revision INTEGER,created_at INTEGER,updated_at INTEGER,deleted_at INTEGER,actor_credential_id TEXT REFERENCES credentials(id));
CREATE TABLE memory_versions(memory_id TEXT REFERENCES memories(id),revision INTEGER,space_id TEXT REFERENCES spaces(id),body TEXT,source TEXT,created_at INTEGER,updated_at INTEGER,deleted_at INTEGER,actor_credential_id TEXT REFERENCES credentials(id),archived_at INTEGER,PRIMARY KEY(memory_id,revision));
CREATE TABLE memory_audit_events(id INTEGER PRIMARY KEY,action TEXT,space_id TEXT REFERENCES spaces(id),memory_id TEXT REFERENCES memories(id),revision INTEGER,actor_credential_id TEXT REFERENCES credentials(id),created_at INTEGER);
CREATE TRIGGER memories_created_audit AFTER INSERT ON memories BEGIN INSERT INTO memory_audit_events(action,space_id,memory_id,revision,actor_credential_id,created_at) VALUES('memory_created',NEW.space_id,NEW.id,NEW.revision,NEW.actor_credential_id,NEW.created_at); END;
CREATE TRIGGER memories_validate_transition BEFORE UPDATE ON memories WHEN NEW.id<>OLD.id OR NEW.space_id<>OLD.space_id OR NEW.created_at<>OLD.created_at OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<OLD.updated_at OR OLD.deleted_at IS NOT NULL OR (NEW.deleted_at IS NOT NULL AND (NEW.body<>OLD.body OR NEW.source IS NOT OLD.source)) BEGIN SELECT RAISE(ABORT,'Invalid memory transition'); END;
CREATE TRIGGER memories_preserve_version AFTER UPDATE ON memories BEGIN INSERT INTO memory_versions(memory_id,revision,space_id,body,source,created_at,updated_at,deleted_at,actor_credential_id,archived_at) VALUES(OLD.id,OLD.revision,OLD.space_id,OLD.body,OLD.source,OLD.created_at,OLD.updated_at,OLD.deleted_at,OLD.actor_credential_id,NEW.updated_at); INSERT INTO memory_audit_events(action,space_id,memory_id,revision,actor_credential_id,created_at) VALUES(CASE WHEN NEW.deleted_at IS NULL THEN 'memory_updated' ELSE 'memory_deleted' END,NEW.space_id,NEW.id,NEW.revision,NEW.actor_credential_id,NEW.updated_at); END;
CREATE TRIGGER memory_versions_no_delete BEFORE DELETE ON memory_versions BEGIN SELECT RAISE(ABORT,'Memory history is append-only'); END;
CREATE TABLE provider_identities(issuer TEXT,subject TEXT,account_id TEXT REFERENCES accounts(id),created_at INTEGER,PRIMARY KEY(issuer,subject));
CREATE TABLE workspace_key_metadata(credential_id TEXT PRIMARY KEY REFERENCES credentials(id),label TEXT,actor_credential_id TEXT REFERENCES credentials(id),created_at INTEGER);
CREATE TABLE domains(id TEXT PRIMARY KEY,organization_id TEXT REFERENCES organizations(id),name TEXT,verified_until INTEGER,revoked_at INTEGER);
CREATE UNIQUE INDEX one_live_domain_owner ON domains(name) WHERE revoked_at IS NULL;
CREATE TABLE domain_managers(domain_id TEXT REFERENCES domains(id),membership_id TEXT REFERENCES memberships(id),revoked_at INTEGER,PRIMARY KEY(domain_id,membership_id));
CREATE TABLE email_challenges(id TEXT PRIMARY KEY,account_id TEXT REFERENCES accounts(id),address TEXT,domain TEXT,token_digest TEXT,expires_at INTEGER,used_at INTEGER,invalidated_at INTEGER);
CREATE TABLE workspace_invitations(id TEXT PRIMARY KEY,organization_id TEXT,address TEXT,role TEXT,token_digest TEXT,creator_membership_id TEXT,actor_credential_id TEXT,created_at INTEGER,expires_at INTEGER,accepted_at INTEGER);
CREATE TABLE workspace_sign_ins(id TEXT PRIMARY KEY,issuer TEXT,subject TEXT,new_account_id TEXT,credential_id TEXT,token_digest TEXT,expires_at INTEGER,permission TEXT,email_id TEXT,address TEXT,domain TEXT,personal_space_id TEXT,created_at INTEGER);
